import 'package:flutter/material.dart';

class SPageScaffold extends StatelessWidget { const SPageScaffold({super.key, required this.body, this.appBar, this.bottomNavigationBar, this.backgroundColor = Colors.white}); final Widget body; final PreferredSizeWidget? appBar; final Widget? bottomNavigationBar; final Color backgroundColor; @override Widget build(BuildContext context) => Scaffold(backgroundColor: backgroundColor, appBar: appBar, body: SafeArea(child: body), bottomNavigationBar: bottomNavigationBar); }
class SSectionHeader extends StatelessWidget { const SSectionHeader({super.key, required this.title, this.action}); final String title; final Widget? action; @override Widget build(BuildContext context) => Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text(title, style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w700)), if (action != null) action!]); }
class SResponsiveContent extends StatelessWidget { const SResponsiveContent({super.key, required this.child, this.maxWidth = 600}); final Widget child; final double maxWidth; @override Widget build(BuildContext context) => Center(child: ConstrainedBox(constraints: BoxConstraints(maxWidth: maxWidth), child: Padding(padding: const EdgeInsets.symmetric(horizontal: 20), child: child))); }
